"356 :   private void flattenReferencesTo(Name n, String alias) {
357 :     String originalName = n.getFullName();
358 :     for (Ref r : n.getRefs()) {
359 :       if (r == n.getDeclaration()) {
360 :         // Declarations are handled separately.
361 :         continue;
362 :       }
363 : 
364 :       Node rParent = r.node.getParent();
365 : 
366 :       // There are two cases when we shouldn't flatten a reference:
367 :       // 1) Object literal keys, because duplicate keys show up as refs.
368 :       // 2) References inside a complex assign. (a = x.y = 0). These are
369 :       //    called TWIN references, because they show up twice in the
370 :       //    reference list. Only collapse the set, not the alias.
371 :       if (!NodeUtil.isObjectLitKey(r.node, rParent) &&
372 :           (r.getTwin() == null || r.isSet())) {
373 :         flattenNameRef(alias, r.node, rParent, originalName);
374 :       }
375 :     }
376 : 
377 :     // Flatten all occurrences of a name as a prefix of its subnames. For
378 :     // example, if {@code n} corresponds to the name "a.b", then "a.b" will be
379 :     // replaced with "a$b" in all occurrences of "a.b.c", "a.b.c.d", etc.
380 :     if (n.props != null) {
381 :       for (Name p : n.props) {
382 :         flattenPrefixes(alias, p, 1);
383 :       }
384 :     }
385 :   }"

"311 :   private void flattenReferencesToCollapsibleDescendantNames(
312 :       Name n, String alias) {
313 :     if (n.props == null) return;
314 : 
315 :     for (Name p : n.props) {
316 :       String propAlias = appendPropForAlias(alias, p.getBaseName());
317 : 
318 :       if (p.canCollapse()) {
319 :         flattenReferencesTo(p, propAlias);
320 :       } else if (p.isSimpleStubDeclaration()) {
321 :         flattenSimpleStubDeclaration(p, propAlias);
322 :       }
323 : 
324 :       flattenReferencesToCollapsibleDescendantNames(p, propAlias);
325 :     }
326 :   }"

