"659 :   private void updateObjLitOrFunctionDeclarationAtAssignNode(
660 :       Name n, String alias, boolean canCollapseChildNames) {
661 :     // NOTE: It's important that we don't add additional nodes
662 :     // (e.g. a var node before the exprstmt) because the exprstmt might be
663 :     // the child of an if statement that's not inside a block).
664 : 
665 :     Ref ref = n.getDeclaration();
666 :     Node rvalue = ref.node.getNext();
667 :     Node varNode = new Node(Token.VAR);
668 :     Node varParent = ref.node.getAncestor(3);
669 :     Node gramps = ref.node.getAncestor(2);
670 :     boolean isObjLit = rvalue.isObjectLit();
671 :     boolean insertedVarNode = false;
672 : 
673 :     if (isObjLit && n.canEliminate()) {
674 :       // Eliminate the object literal altogether.
675 :       varParent.replaceChild(gramps, varNode);
676 :       ref.node = null;
677 :       insertedVarNode = true;
678 : 
679 :     } else if (!n.isSimpleName()) {
680 :       // Create a VAR node to declare the name.
681 :       if (rvalue.isFunction()) {
682 :         checkForHosedThisReferences(rvalue, n.docInfo, n);
683 :       }
684 : 
685 :       ref.node.getParent().removeChild(rvalue);
686 : 
687 :       Node nameNode = NodeUtil.newName(
688 :           compiler.getCodingConvention(),
689 :           alias, ref.node.getAncestor(2), n.getFullName());
690 : 
691 :       JSDocInfo info = ref.node.getParent().getJSDocInfo();
692 :       if (ref.node.getLastChild().getBooleanProp(Node.IS_CONSTANT_NAME) ||
693 :           (info != null && info.isConstant())) {
694 :         nameNode.putBooleanProp(Node.IS_CONSTANT_NAME, true);
695 :       }
696 : 
697 :       varNode.addChildToBack(nameNode);
698 :       nameNode.addChildToFront(rvalue);
699 :       varParent.replaceChild(gramps, varNode);
700 : 
701 :       // Update the node ancestry stored in the reference.
702 :       ref.node = nameNode;
703 :       insertedVarNode = true;
704 :     }
705 : 
706 :     if (canCollapseChildNames) {
707 :       if (isObjLit) {
708 :         declareVarsForObjLitValues(
709 :             n, alias, rvalue,
710 :             varNode, varParent.getChildBefore(varNode), varParent);
711 :       }
712 : 
713 :       addStubsForUndeclaredProperties(n, alias, varParent, varNode);
714 :     }
715 : 
716 :     if (insertedVarNode) {
717 :       if (!varNode.hasChildren()) {
718 :         varParent.removeChild(varNode);
719 :       }
720 :       compiler.reportCodeChange();
721 :     }
722 :   }"

"622 :   private void updateObjLitOrFunctionDeclaration(
623 :       Name n, String alias, boolean canCollapseChildNames) {
624 :     Ref decl = n.getDeclaration();
625 :     if (decl == null) {
626 :       // Some names do not have declarations, because they
627 :       // are only defined in local scopes.
628 :       return;
629 :     }
630 : 
631 :     if (decl.getTwin() != null) {
632 :       // Twin declarations will get handled when normal references
633 :       // are handled.
634 :       return;
635 :     }
636 : 
637 :     switch (decl.node.getParent().getType()) {
638 :       case Token.ASSIGN:
639 :         updateObjLitOrFunctionDeclarationAtAssignNode(
640 :             n, alias, canCollapseChildNames);
641 :         break;
642 :       case Token.VAR:
643 :         updateObjLitOrFunctionDeclarationAtVarNode(n, canCollapseChildNames);
644 :         break;
645 :       case Token.FUNCTION:
646 :         updateFunctionDeclarationAtFunctionNode(n, canCollapseChildNames);
647 :         break;
648 :     }
649 :   }"

"958 :   private static String appendPropForAlias(String root, String prop) {
959 :     if (prop.indexOf('$') != -1) {
960 :       // Encode '$' in a property as '$0'. Because '0' cannot be the
961 :       // start of an identifier, this will never conflict with our
962 :       // encoding from '.' -> '$'.
963 :       prop = prop.replaceAll("\\$", "\\$0");
964 :     }
965 :     return root + '$' + prop;
966 :   }"

"249 :   private void checkNamespaces() {
250 :     for (Name name : nameMap.values()) {
251 :       if (name.isNamespace() &&
252 :           (name.aliasingGets > 0 || name.localSets + name.globalSets > 1 ||
253 :            name.deleteProps > 0)) {
254 :         boolean initialized = name.getDeclaration() != null;
255 :         for (Ref ref : name.getRefs()) {
256 :           if (ref == name.getDeclaration()) {
257 :             continue;
258 :           }
259 : 
260 :           if (ref.type == Ref.Type.DELETE_PROP) {
261 :             if (initialized) {
262 :               warnAboutNamespaceRedefinition(name, ref);
263 :             }
264 :           } else if (
265 :               ref.type == Ref.Type.SET_FROM_GLOBAL ||
266 :               ref.type == Ref.Type.SET_FROM_LOCAL) {
267 :             if (initialized) {
268 :               warnAboutNamespaceRedefinition(name, ref);
269 :             }
270 : 
271 :             initialized = true;
272 :           } else if (ref.type == Ref.Type.ALIASING_GET) {
273 :             warnAboutNamespaceAliasing(name, ref);
274 :           }
