"643 :     void handleGet(NodeTraversal t, Node n, Node parent, String name) {
644 :       if (maybeHandlePrototypePrefix(t, n, parent, name)) return;
645 : 
646 :       Ref.Type type = Ref.Type.DIRECT_GET;
647 :       if (parent != null) {
648 :         switch (parent.getType()) {
649 :           case Token.IF:
650 :           case Token.TYPEOF:
651 :           case Token.VOID:
652 :           case Token.NOT:
653 :           case Token.BITNOT:
654 :           case Token.POS:
655 :           case Token.NEG:
656 :             break;
657 :           case Token.CALL:
658 :             type = n == parent.getFirstChild()
659 :                    ? Ref.Type.CALL_GET
660 :                    : Ref.Type.ALIASING_GET;
661 :             break;
662 :           case Token.NEW:
663 :             type = n == parent.getFirstChild()
664 :                    ? Ref.Type.DIRECT_GET
665 :                    : Ref.Type.ALIASING_GET;
666 :             break;
667 :           case Token.OR:
668 :           case Token.AND:
669 :             // This node is x or y in (x||y) or (x&&y). We only know that an
670 :             // alias is not getting created for this name if the result is used
671 :             // in a boolean context or assigned to the same name
672 :             // (e.g. var a = a || {}).
673 :             type = determineGetTypeForHookOrBooleanExpr(t, parent, name);
674 :             break;
675 :           case Token.HOOK:
676 :             if (n != parent.getFirstChild()) {
677 :               // This node is y or z in (x?y:z). We only know that an alias is
678 :               // not getting created for this name if the result is assigned to
679 :               // the same name (e.g. var a = a ? a : {}).
680 :               type = determineGetTypeForHookOrBooleanExpr(t, parent, name);
681 :             }
682 :             break;
683 :           case Token.DELPROP:
684 :             type = Ref.Type.DELETE_PROP;
685 :             break;
686 :           default:
687 :             type = Ref.Type.ALIASING_GET;
688 :             break;
689 :         }
690 :       }
691 : 
692 :       handleGet(t, n, parent, name, type);
693 :     }"

"544 :     void handleSetFromGlobal(NodeTraversal t, Node n, Node parent, String name,
545 :                              boolean isPropAssign, Name.Type type) {
546 :       if (maybeHandlePrototypePrefix(t, n, parent, name)) return;
547 : 
548 :       Name nameObj = getOrCreateName(name);
549 :       nameObj.type = type;
550 : 
551 :       Ref set = new Ref(t, n, nameObj, Ref.Type.SET_FROM_GLOBAL,
552 :           currentPreOrderIndex++);
553 :       nameObj.addRef(set);
554 : 
555 :       if (isNestedAssign(parent)) {
556 :         // This assignment is both a set and a get that creates an alias.
557 :         Ref get = new Ref(t, n, nameObj, Ref.Type.ALIASING_GET,
558 :             currentPreOrderIndex++);
559 :         nameObj.addRef(get);
560 :         Ref.markTwins(set, get);
561 :       } else if (isConstructorOrEnumDeclaration(n, parent)) {
562 :         // Names with a @constructor or @enum annotation are always collapsed
563 :         nameObj.setIsClassOrEnum();
