"1067 :     boolean canCollapseUnannotatedChildNames() {
1068 :       if (type == Type.OTHER || isGetOrSetDefinition()
1069 :           || globalSets != 1 || localSets != 0 || deleteProps != 0) {
1070 :         return false;
1071 :       }
1072 : 
1073 :       // Don't try to collapse if the one global set is a twin reference.
1074 :       // We could theoretically handle this case in CollapseProperties, but
1075 :       // it's probably not worth the effort.
1076 :       Preconditions.checkNotNull(declaration);
1077 :       if (declaration.getTwin() != null) {
1078 :         return false;
1079 :       }
1080 : 
1081 :       if (isClassOrEnum) {
1082 :         return true;
1083 :       }
1084 : 
1085 :       // If this is a key of an aliased object literal, then it will be aliased
1086 :       // later. So we won't be able to collapse its properties.
1087 :       if (parent != null && parent.shouldKeepKeys()) {
1088 :         return false;
1089 :       }
1090 : 
1091 :       // If this is aliased, then its properties can't be collapsed either.
1092 :       if (aliasingGets > 0) {
1093 :         return false;
1094 :       }
1095 : 
1096 :       return (parent == null || parent.canCollapseUnannotatedChildNames());
1097 :     }"

"1056 :     boolean canCollapse() {
1057 :       return !inExterns && !isGetOrSetDefinition() && (isClassOrEnum ||
1058 :           (parent == null || parent.canCollapseUnannotatedChildNames()) &&
1059 :           (globalSets > 0 || localSets > 0) &&
1060 :           deleteProps == 0);
1061 :     }"

"781 :     boolean maybeHandlePrototypePrefix(NodeTraversal t, Node n, Node parent,
782 :         String name) {
783 :       // We use a string-based approach instead of inspecting the parse tree
784 :       // to avoid complexities with object literals, possibly nested, beneath
785 :       // assignments.
786 : 
787 :       int numLevelsToRemove;
788 :       String prefix;
789 :       if (name.endsWith(".prototype")) {
790 :         numLevelsToRemove = 1;
791 :         prefix = name.substring(0, name.length() - 10);
792 :       } else {
793 :         int i = name.indexOf(".prototype.");
794 :         if (i == -1) {
795 :           return false;
796 :         }
797 :         prefix = name.substring(0, i);
798 :         numLevelsToRemove = 2;
799 :         i = name.indexOf('.', i + 11);
800 :         while (i >= 0) {
801 :           numLevelsToRemove++;
802 :           i = name.indexOf('.', i + 1);
803 :         }
804 :       }
805 : 
806 :       if (parent != null && NodeUtil.isObjectLitKey(n, parent)) {
807 :         // Object literal keys have no prefix that's referenced directly per
808 :         // key, so we're done.
809 :         return true;
810 :       }
811 : 
812 :       for (int i = 0; i < numLevelsToRemove; i++) {
813 :         parent = n;
814 :         n = n.getFirstChild();
815 :       }
816 : 
817 :       handleGet(t, n, parent, prefix, Ref.Type.PROTOTYPE_GET);
818 :       return true;
819 :     }"

"422 :     private boolean processGlobalFunctionDeclaration(NodeTraversal t,
423 :         Node nameNode, Var v) {
424 :       Node firstChild = nameNode.getFirstChild();
425 :       Node parent = nameNode.getParent();
426 : 
427 :       if (// Check for a named FUNCTION.
428 :           isGlobalFunctionDeclaration(t, parent) ||
429 :           // Check for a VAR declaration.
430 :           firstChild != null &&
431 :           isGlobalFunctionDeclaration(t, firstChild)) {
432 :         String name = nameNode.getString();
433 :         getNameInfoForName(name, VAR).getDeclarations().add(
434 :             new GlobalFunction(nameNode, v, t.getModule()));
435 : 
436 :         // If the function name is exported, we should create an edge here
437 :         // so that it's never removed.
438 :         if (compiler.getCodingConvention().isExported(name) ||
439 :             anchorUnusedVars) {
440 :           addGlobalUseOfSymbol(name, t.getModule(), VAR);
441 :         }
442 : 
443 :         return true;
444 :       }
445 :       return false;
