"249 :     @Override
250 :     public void visit(NodeTraversal t, Node n, Node parent) {
251 :       if (n.isGetProp()) {
252 :         String propName = n.getFirstChild().getNext().getString();
253 : 
254 :         if (n.isQualifiedName()) {
255 :           if (propName.equals("prototype")) {
256 :             if (processPrototypeRef(t, n)) {
257 :               return;
258 :             }
259 :           } else if (compiler.getCodingConvention().isExported(propName)) {
260 :             addGlobalUseOfSymbol(propName, t.getModule(), PROPERTY);
261 :             return;
262 :           } else {
263 :             // Do not mark prototype prop assigns as a 'use' in the global scope.
264 :             if (n.getParent().isAssign() && n.getNext() != null) {
265 :               String rValueName = getPrototypePropertyNameFromRValue(n);
266 :               if (rValueName != null) {
267 :                 return;
268 :               }
269 :             }
270 :           }
271 :         }
272 : 
273 :         addSymbolUse(propName, t.getModule(), PROPERTY);
274 :       } else if (n.isObjectLit()) {
275 :         // Make sure that we're not handling object literals being
276 :         // assigned to a prototype, as in:
277 :         // Foo.prototype = {bar: 3, baz: 5};
278 :         String lValueName = NodeUtil.getBestLValueName(
279 :             NodeUtil.getBestLValue(n));
280 :         if (lValueName != null && lValueName.endsWith(".prototype")) {
281 :           return;
282 :         }
283 : 
284 :         // var x = {a: 1, b: 2}
285 :         // should count as a use of property a and b.
286 :         for (Node propNameNode = n.getFirstChild(); propNameNode != null;
287 :              propNameNode = propNameNode.getNext()) {
288 :           // May be STRING, GET, or SET, but NUMBER isn't interesting.
289 :           if (!propNameNode.isQuotedString()) {
290 :             addSymbolUse(propNameNode.getString(), t.getModule(), PROPERTY);
291 :           }
292 :         }
293 :       } else if (n.isName()) {
294 :         String name = n.getString();
295 : 
296 :         Var var = t.getScope().getVar(name);
297 :         if (var != null) {
298 :           // Only process global functions.
299 :           if (var.isGlobal()) {
300 :             if (var.getInitialValue() != null &&
301 :                 var.getInitialValue().isFunction()) {
302 :               if (t.inGlobalScope()) {
303 :                 if (!processGlobalFunctionDeclaration(t, n, var)) {
304 :                   addGlobalUseOfSymbol(name, t.getModule(), VAR);
305 :                 }
306 :               } else {
307 :                 addSymbolUse(name, t.getModule(), VAR);
308 :               }
309 :             }
310 : 
311 :           // If it is not a global, it might be accessing a local of the outer
312 :           // scope. If that's the case the functions between the variable's
313 :           // declaring scope and the variable reference scope cannot be moved.
314 :           } else if (var.getScope() != t.getScope()){
315 :             for (int i = symbolStack.size() - 1; i >= 0; i--) {
316 :               NameContext context = symbolStack.get(i);
317 :               if (context.scope == var.getScope()) {
318 :                 break;
319 :               }
320 : 
321 :               context.name.readClosureVariables = true;
322 :             }
323 :           }
324 :         }
325 :       }
326 : 
327 :       // Process prototype assignments to non-functions.
328 :       if (processNonFunctionPrototypeAssign(n, parent) != null) {
329 :         symbolStack.pop();
330 :       }
331 :     }"

"454 :     private boolean processPrototypeRef(NodeTraversal t, Node ref) {
455 :       Node root = NodeUtil.getRootOfQualifiedName(ref);
456 : 
457 :       Node n = ref.getParent();
458 :       switch (n.getType()) {
459 :         // Foo.prototype.getBar = function() { ... }
460 :         case Token.GETPROP:
461 :           Node dest = n.getFirstChild().getNext();
462 :           Node parent = n.getParent();
463 :           Node grandParent = parent.getParent();
464 : 
465 :           if (dest.isString() &&
466 :               NodeUtil.isExprAssign(grandParent) &&
467 :               NodeUtil.isVarOrSimpleAssignLhs(n, parent)) {
468 :             String name = dest.getString();
469 :             Property prop = new AssignmentProperty(
470 :                 grandParent,
471 :                 maybeGetVar(t, root),
472 :                 t.getModule());
473 :             getNameInfoForName(name, PROPERTY).getDeclarations().add(prop);
474 :             return true;
475 :           }
476 :           break;
477 : 
478 :         // Foo.prototype = { "getBar" : function() { ... } }
479 :         case Token.ASSIGN:
480 :           Node map = n.getFirstChild().getNext();
481 :           if (map.isObjectLit()) {
482 :             for (Node key = map.getFirstChild();
483 :                  key != null; key = key.getNext()) {
484 :               // May be STRING, GETTER_DEF, or SETTER_DEF,
485 :               String name = key.getString();
486 :               Property prop = new LiteralProperty(
487 :                   key, key.getFirstChild(), map, n,
488 :                   maybeGetVar(t, root),
489 :                   t.getModule());
490 :               getNameInfoForName(name, PROPERTY).getDeclarations().add(prop);
491 :             }
492 :             return true;
493 :           }
494 :           break;
495 :       }
496 :       return false;
497 :     }"

