"659 :   private void updateObjLitOrFunctionDeclarationAtAssignNode(
660 :       Name n, String alias, boolean canCollapseChildNames) {
661 :     // NOTE: It's important that we don't add additional nodes
662 :     // (e.g. a var node before the exprstmt) because the exprstmt might be
663 :     // the child of an if statement that's not inside a block).
664 : 
665 :     Ref ref = n.getDeclaration();
666 :     Node rvalue = ref.node.getNext();
667 :     Node varNode = new Node(Token.VAR);
668 :     Node varParent = ref.node.getAncestor(3);
669 :     Node gramps = ref.node.getAncestor(2);
670 :     boolean isObjLit = rvalue.isObjectLit();
671 :     boolean insertedVarNode = false;
672 : 
673 :     if (isObjLit && n.canEliminate()) {
674 :       // Eliminate the object literal altogether.
675 :       varParent.replaceChild(gramps, varNode);
676 :       ref.node = null;
677 :       insertedVarNode = true;
678 : 
679 :     } else if (!n.isSimpleName()) {
680 :       // Create a VAR node to declare the name.
681 :       if (rvalue.isFunction()) {
682 :         checkForHosedThisReferences(rvalue, n.docInfo, n);
683 :       }
684 : 
685 :       ref.node.getParent().removeChild(rvalue);
686 : 
687 :       Node nameNode = NodeUtil.newName(
688 :           compiler.getCodingConvention(),
689 :           alias, ref.node.getAncestor(2), n.getFullName());
690 : 
691 :       JSDocInfo info = ref.node.getParent().getJSDocInfo();
692 :       if (ref.node.getLastChild().getBooleanProp(Node.IS_CONSTANT_NAME) ||
693 :           (info != null && info.isConstant())) {
694 :         nameNode.putBooleanProp(Node.IS_CONSTANT_NAME, true);
695 :       }
696 : 
697 :       varNode.addChildToBack(nameNode);
698 :       nameNode.addChildToFront(rvalue);
699 :       varParent.replaceChild(gramps, varNode);
700 : 
701 :       // Update the node ancestry stored in the reference.
702 :       ref.node = nameNode;
703 :       insertedVarNode = true;
704 :     }
705 : 
706 :     if (canCollapseChildNames) {
707 :       if (isObjLit) {
708 :         declareVarsForObjLitValues(
709 :             n, alias, rvalue,
710 :             varNode, varParent.getChildBefore(varNode), varParent);
711 :       }
712 : 
713 :       addStubsForUndeclaredProperties(n, alias, varParent, varNode);
714 :     }
715 : 
716 :     if (insertedVarNode) {
717 :       if (!varNode.hasChildren()) {
718 :         varParent.removeChild(varNode);
719 :       }
720 :       compiler.reportCodeChange();
721 :     }
722 :   }"

