"622 :   private void updateObjLitOrFunctionDeclaration(
623 :       Name n, String alias, boolean canCollapseChildNames) {
624 :     Ref decl = n.getDeclaration();
625 :     if (decl == null) {
626 :       // Some names do not have declarations, because they
627 :       // are only defined in local scopes.
628 :       return;
629 :     }
630 : 
631 :     if (decl.getTwin() != null) {
632 :       // Twin declarations will get handled when normal references
633 :       // are handled.
634 :       return;
635 :     }
636 : 
637 :     switch (decl.node.getParent().getType()) {
638 :       case Token.ASSIGN:
639 :         updateObjLitOrFunctionDeclarationAtAssignNode(
640 :             n, alias, canCollapseChildNames);
641 :         break;
642 :       case Token.VAR:
643 :         updateObjLitOrFunctionDeclarationAtVarNode(n, canCollapseChildNames);
644 :         break;
645 :       case Token.FUNCTION:
646 :         updateFunctionDeclarationAtFunctionNode(n, canCollapseChildNames);
647 :         break;
648 :     }
