"958 :   private static String appendPropForAlias(String root, String prop) {
959 :     if (prop.indexOf('$') != -1) {
960 :       // Encode '$' in a property as '$0'. Because '0' cannot be the
961 :       // start of an identifier, this will never conflict with our
962 :       // encoding from '.' -> '$'.
963 :       prop = prop.replaceAll("\\$", "\\$0");
964 :     }
965 :     return root + '$' + prop;
966 :   }"

