"462 :   private void flattenNameRef(String alias, Node n, Node parent,
463 :       String originalName) {
464 :     // BEFORE:
465 :     //   getprop
466 :     //     getprop
467 :     //       name a
468 :     //       string b
469 :     //     string c
470 :     // AFTER:
471 :     //   name a$b$c
