"175 :   @Override
176 :   public void visit(NodeTraversal t, Node n, Node parent) {
177 :     switch (n.getType()) {
178 :       case Token.CALL:
179 :         boolean isExpr = parent.isExprResult();
180 :         Node left = n.getFirstChild();
181 :         if (left.isGetProp()) {
182 :           Node name = left.getFirstChild();
183 :           if (name.isName() &&
184 :               GOOG.equals(name.getString())) {
185 :             // For the sake of simplicity, we report code changes
186 :             // when we see a provides/requires, and don't worry about
187 :             // reporting the change when we actually do the replacement.
188 :             String methodName = name.getNext().getString();
189 :             if ("base".equals(methodName)) {
190 :               processBaseClassCall(t, n);
191 :             } else if (!isExpr) {
192 :               // All other methods must be called in an EXPR.
193 :               break;
194 :             } else if ("require".equals(methodName)) {
195 :               processRequireCall(t, n, parent);
196 :             } else if ("provide".equals(methodName)) {
197 :               processProvideCall(t, n, parent);
198 :             } else if ("exportSymbol".equals(methodName)) {
199 :               Node arg = left.getNext();
200 :               if (arg.isString()) {
201 :                 int dot = arg.getString().indexOf('.');
202 :                 if (dot == -1) {
203 :                   exportedVariables.add(arg.getString());
204 :                 } else {
205 :                   exportedVariables.add(arg.getString().substring(0, dot));
206 :                 }
207 :               }
208 :             } else if ("addDependency".equals(methodName)) {
209 :               CodingConvention convention = compiler.getCodingConvention();
210 :               List<String> typeDecls =
211 :                   convention.identifyTypeDeclarationCall(n);
212 :               if (typeDecls != null) {
213 :                 for (String typeDecl : typeDecls) {
214 :                   compiler.getTypeRegistry().forwardDeclareType(typeDecl);
215 :                 }
216 :               }
217 : 
218 :               // We can't modify parent, so just create a node that will
219 :               // get compiled out.
220 :               parent.replaceChild(n, IR.number(0));
221 :               compiler.reportCodeChange();
222 :             } else if ("setCssNameMapping".equals(methodName)) {
223 :               processSetCssNameMapping(t, n, parent);
224 :             }
225 :           }
226 :         }
227 :         break;
228 : 
229 :       case Token.ASSIGN:
230 :       case Token.NAME:
231 :         // If this is an assignment to a provided name, remove the provided
232 :         // object.
233 :         handleCandidateProvideDefinition(t, n, parent);
234 :         break;
235 : 
236 :       case Token.EXPR_RESULT:
237 :         handleTypedefDefinition(t, n, parent);
238 :         break;
239 : 
240 :       case Token.FUNCTION:
241 :         // If this is a declaration of a provided named function, this is an
242 :         // error. Hosited functions will explode if the're provided.
243 :         if (t.inGlobalScope() &&
244 :             !NodeUtil.isFunctionExpression(n)) {
245 :           String name = n.getFirstChild().getString();
246 :           ProvidedName pn = providedNames.get(name);
247 :           if (pn != null) {
248 :             compiler.report(t.makeError(n, FUNCTION_NAMESPACE_ERROR, name));
249 :           }
250 :         }
251 :         break;
252 : 
253 :       case Token.NEW:
254 :         trySimplifyNewDate(t, n, parent);
255 :         break;
256 : 
257 :       case Token.GETPROP:
258 :         if (n.getFirstChild().isName() &&
259 :             !parent.isCall() &&
260 :             !parent.isAssign() &&
261 :             "goog.base".equals(n.getQualifiedName())) {
262 :           reportBadBaseClassUse(t, n, "May only be called directly.");
263 :         }
264 :         break;
265 :     }
266 :   }"

