"422 :     private boolean processGlobalFunctionDeclaration(NodeTraversal t,
423 :         Node nameNode, Var v) {
424 :       Node firstChild = nameNode.getFirstChild();
425 :       Node parent = nameNode.getParent();
426 : 
427 :       if (// Check for a named FUNCTION.
428 :           isGlobalFunctionDeclaration(t, parent) ||
429 :           // Check for a VAR declaration.
430 :           firstChild != null &&
431 :           isGlobalFunctionDeclaration(t, firstChild)) {
432 :         String name = nameNode.getString();
433 :         getNameInfoForName(name, VAR).getDeclarations().add(
434 :             new GlobalFunction(nameNode, v, t.getModule()));
435 : 
436 :         // If the function name is exported, we should create an edge here
437 :         // so that it's never removed.
438 :         if (compiler.getCodingConvention().isExported(name) ||
439 :             anchorUnusedVars) {
