"454 :     private boolean processPrototypeRef(NodeTraversal t, Node ref) {
455 :       Node root = NodeUtil.getRootOfQualifiedName(ref);
456 : 
457 :       Node n = ref.getParent();
458 :       switch (n.getType()) {
459 :         // Foo.prototype.getBar = function() { ... }
460 :         case Token.GETPROP:
461 :           Node dest = n.getFirstChild().getNext();
462 :           Node parent = n.getParent();
463 :           Node grandParent = parent.getParent();
464 : 
465 :           if (dest.isString() &&
466 :               NodeUtil.isExprAssign(grandParent) &&
467 :               NodeUtil.isVarOrSimpleAssignLhs(n, parent)) {
468 :             String name = dest.getString();
469 :             Property prop = new AssignmentProperty(
470 :                 grandParent,
471 :                 maybeGetVar(t, root),
472 :                 t.getModule());
473 :             getNameInfoForName(name, PROPERTY).getDeclarations().add(prop);
474 :             return true;
475 :           }
476 :           break;
477 : 
478 :         // Foo.prototype = { "getBar" : function() { ... } }
479 :         case Token.ASSIGN:
480 :           Node map = n.getFirstChild().getNext();
481 :           if (map.isObjectLit()) {
482 :             for (Node key = map.getFirstChild();
483 :                  key != null; key = key.getNext()) {
484 :               // May be STRING, GETTER_DEF, or SETTER_DEF,
485 :               String name = key.getString();
486 :               Property prop = new LiteralProperty(
487 :                   key, key.getFirstChild(), map, n,
488 :                   maybeGetVar(t, root),
489 :                   t.getModule());
490 :               getNameInfoForName(name, PROPERTY).getDeclarations().add(prop);
491 :             }
492 :             return true;
493 :           }
494 :           break;
495 :       }
496 :       return false;
497 :     }"

